import com.Akeltroll.dragonsofberk.config.util.ConfigHelper;
import net.minecraftforge.common.ForgeConfigSpec;

public class ClientConfig {
    public ConfigHelper.ConfigValueListener<Boolean> transitionToggle;
    public ConfigHelper.ConfigValueListener<Boolean> disableCameraRoll;

    public ClientConfig(ForgeConfigSpec.Builder builder, ConfigHelper.Subscriber subscriber) {
        builder.comment("Dragons of Berk Main Config").push("Animation fix for shaders");
        this.transitionToggle = subscriber.subscribe(builder.comment("Set to true if you experience issues with animations when using shaders").define("disable_transition_ticks", false));
        builder.pop();
        builder.push("Flight camera");
        this.disableCameraRoll = subscriber.subscribe(builder.comment("Set to true to stop the camera from rolling (banking) with the dragon while flying. Does not affect the visible tilt of the dragon/rider model, only the camera view.").define("disable_camera_roll", false));
        builder.pop();
    }
}

